def generate_signals(features, signal_params):
    import numpy as np
    n = features.market.size
    order_block_candle_count = signal_params['order_block_candle_count']
    order_block_width_atr_multiplier = signal_params['order_block_width_atr_multiplier']
    minimum_fvg_size_atr_multiplier = signal_params['minimum_fvg_size_atr_multiplier']
    support_resistance_tolerance_points = signal_params['support_resistance_tolerance_points']
    point_value = signal_params['point_value']
    stop_loss_buffer = signal_params['stop_loss_buffer']
    take_profit_1_risk_multiplier = signal_params['take_profit_1_risk_multiplier']
    take_profit_2_risk_multiplier = signal_params['take_profit_2_risk_multiplier']
    take_profit_3_risk_multiplier = signal_params['take_profit_3_risk_multiplier']
    take_profit_1_stop_adjustment = signal_params['take_profit_1_stop_adjustment']
    opens = np.asarray(features.market.opens, dtype=np.float64)
    highs = np.asarray(features.market.highs, dtype=np.float64)
    lows = np.asarray(features.market.lows, dtype=np.float64)
    closes = np.asarray(features.market.closes, dtype=np.float64)
    atr = np.asarray(features.atr(22), dtype=np.float64)
    long_entries = np.zeros(n, dtype=bool)
    short_entries = np.zeros(n, dtype=bool)
    long_exits = np.zeros(n, dtype=bool)
    short_exits = np.zeros(n, dtype=bool)
    stop_distances = np.full(n, np.nan, dtype=np.float64)
    target_distances = np.full(n, np.nan, dtype=np.float64)
    count = max(1, int(order_block_candle_count))
    tolerance = float(support_resistance_tolerance_points) * float(point_value)
    buffer_distance = float(stop_loss_buffer) * float(point_value)
    pivot_lows = np.asarray(features.pivot_low(2, 2), dtype=np.float64)
    pivot_highs = np.asarray(features.pivot_high(2, 2), dtype=np.float64)
    prior_highs = np.concatenate(([np.nan], np.asarray(features.highest(count, 'highs')[:-1], dtype=np.float64)))
    prior_lows = np.concatenate(([np.nan], np.asarray(features.lowest(count, 'lows')[:-1], dtype=np.float64)))
    long_zone = None
    short_zone = None
    bullish_gaps = []
    bearish_gaps = []
    for t in range(n):
        if t >= 2 and np.isfinite(atr[t]):
            bullish_gap_size = lows[t] - highs[t - 2]
            if bullish_gap_size > 0 and bullish_gap_size >= atr[t] * float(minimum_fvg_size_atr_multiplier):
                bullish_gaps.append((float(highs[t - 2]), float(lows[t])))
            bearish_gap_size = lows[t - 2] - highs[t]
            if bearish_gap_size > 0 and bearish_gap_size >= atr[t] * float(minimum_fvg_size_atr_multiplier):
                bearish_gaps.append((float(highs[t]), float(lows[t - 2])))
        bullish_gaps = [(a, b) for a, b in bullish_gaps if lows[t] > a]
        bearish_gaps = [(a, b) for a, b in bearish_gaps if highs[t] < b]
        start = max(0, t - count)
        if t > 0 and t - start >= 1 and np.isfinite(atr[t]):
            if closes[t] > prior_highs[t]:
                candidates = [j for j in range(start, t) if closes[j] < opens[j]]
                if candidates:
                    j = candidates[-1]
                    width = highs[j] - lows[j]
                    if width > 0 and width <= atr[t] * float(order_block_width_atr_multiplier):
                        long_zone = (float(lows[j]), float(highs[j]))
            if closes[t] < prior_lows[t]:
                candidates = [j for j in range(start, t) if closes[j] > opens[j]]
                if candidates:
                    j = candidates[-1]
                    width = highs[j] - lows[j]
                    if width > 0 and width <= atr[t] * float(order_block_width_atr_multiplier):
                        short_zone = (float(lows[j]), float(highs[j]))
        if long_zone is not None and closes[t] < long_zone[0] - buffer_distance:
            long_zone = None
        if short_zone is not None and closes[t] > short_zone[1] + buffer_distance:
            short_zone = None
        if long_zone is not None:
            zone_low, zone_high = long_zone
            support_ok = np.isfinite(pivot_lows[t]) and zone_low - tolerance <= pivot_lows[t] <= zone_high + tolerance
            gap_ok = any((gap_low >= zone_high and gap_high <= lows[t] for gap_low, gap_high in bullish_gaps))
            touched = lows[t] <= zone_high and highs[t] >= zone_low
            if support_ok and gap_ok and touched:
                entry_price = zone_high
                initial_stop = zone_low - buffer_distance
                risk = entry_price - initial_stop
                if risk > 0:
                    long_entries[t] = True
                    stop_distances[t] = risk
                    target_distances[t] = risk * float(take_profit_3_risk_multiplier)
        if short_zone is not None:
            zone_low, zone_high = short_zone
            resistance_ok = np.isfinite(pivot_highs[t]) and zone_low - tolerance <= pivot_highs[t] <= zone_high + tolerance
            gap_ok = any((gap_high <= zone_low and gap_low >= highs[t] for gap_low, gap_high in bearish_gaps))
            touched = highs[t] >= zone_low and lows[t] <= zone_high
            if resistance_ok and gap_ok and touched:
                entry_price = zone_low
                initial_stop = zone_high + buffer_distance
                risk = initial_stop - entry_price
                if risk > 0:
                    short_entries[t] = True
                    stop_distances[t] = risk
                    target_distances[t] = risk * float(take_profit_3_risk_multiplier)
    return (long_entries, long_exits, short_entries, short_exits, stop_distances, target_distances)

